def max_path_sum(triangle, n, m):
    dp = [[0 for i in range(m)] for j in range(n)]
    dp[0][0] = triangle[0][0]
    for i in range(1, n):
        for j in range(0, i + 1):
            if j == 0:
                dp[i][j] = dp[i - 1][j] + triangle[i][j]
            elif j == i:
                dp[i][j] = dp[i - 1][j - 1] + triangle[i][j]
            else:
                dp[i][j] = max(dp[i - 1][j - 1], dp[i - 1][j]) + triangle[i][j]
    return max(dp[n - 1])
```

