def max_sub_array_sum_repeated(arr, k, n):
    max_so_far = -float('inf')
    max_ending_here = 0
    for i in range(0, n):
        max_ending_here = max_ending_here + arr[i]
        if max_ending_here < 0:
            max_ending_here = 0
        elif (max_so_far < max_ending_here):
            max_so_far = max_ending_here
    if (max_so_far < 0):
        return 0
    if (k <= n):
        return max_so_far
    else:
        k = k % n
        if (k == 0):
            return max_so_far
        else:
            return (max_so_far * (n // k)) + (max_sub_array_sum_repeated(arr, k, n % k))
