def find_minimum_range(arrays):
    min_range = float('inf')
    min_start = 0
    max_end = 0
    min_element = float('inf')
    max_element = float('-inf')
    for i in range(len(arrays)):
        min_element = min(min_element, arrays[i][0])
        max_element = max(max_element, arrays[i][-1])
    while min_element <= max_element:
        for i in range(len(arrays)):
            if min_element in arrays[i]:
                break
        for j in range(len(arrays)):
            if max_element in arrays[j]:
                break
        if min_element <= max_element:
            if max_element - min_element < min_range:
                min_range = max_element - min_element
                min_start = min_element
                max_end = max_element
        min_element += 1
        max_element -= 1
    return (min_start, max_end)
```

