def get_maxgold(grid, m, n): 
    if (m < 1 or n < 1): 
        return 0
    dp = [[0 for i in range(n)] for j in range(m)] 
    dp[0][0] = grid[0][0] 
    for i in range(1, n): 
        dp[0][i] = dp[0][i - 1] + grid[0][i] 
    for i in range(1, m): 
        dp[i][0] = dp[i - 1][0] + grid[i][0] 
    for i in range(1, m): 
        for j in range(1, n): 
            dp[i][j] = max(dp[i - 1][j], dp[i][j - 1]) + grid[i][j] 
    return dp[m - 1][n - 1] 
